def build_comp(b):
    for level in range(6, 10):
        for passage, questions in P[level]:
            for prompt, correct, wrong, expl in questions:
                b.mc(M, level, prompt, correct, wrong, expl, passage=passage)
        for sentence, blanks, distr, expl in FILL[level]:
            b.fill(M, level, "Completa la frase con las palabras correctas", sentence, blanks, distr, expl)


def build_readings(b):
    for level in range(6, 10):
        for rid, title, emoji, text, questions in READINGS[level]:
            b.reading(rid, level, title, emoji, text, questions)
